// 复用已验真实组件初态，只跑新命令薄叶和有限页；不重跑原153项完整链。
#define main previous_governance_component_entry
#include "politics_governance_joint_test.cpp"
#undef main
#include "resident/kernel/governance_integration.hpp"
#include "resident/domains/politics/politics_governance_profile.hpp"
namespace {
// 本门读取同一真实三域初态，动作释放复用Common资源与人物占用的原三步写入。
struct EntryWorld:JointWorld {
    PoliticsCatalog politics_catalog;SocialState social;PoliticsViewIndex political_index;GovernanceViewIndex governance_index;
    EntryWorld(){politics_catalog.enabled=true;politics_catalog.jurisdictions=politics.jurisdictions;catalog->actor_names.insert("worker",{"worker.name"});catalog->texts.insert("worker.name","执行人");catalog->actor_names.insert("official",{"official.name"});catalog->texts.insert("official.name","本地官员");refresh();}
    void refresh(){political_index=make_politics_view_index(common,politics,organization,organization_catalog,social);governance_index=make_governance_view_index(common,governance,tasks,task_governance);}
    GovernanceReadContext read(){return {common,*catalog,politics,politics_catalog,governance,governance_catalog,organization,organization_catalog,economy,relief_catalog,relief,tasks,task_governance,activity,&political_index,&governance_index};}
    GovernanceWriteContext write(){return {common,*catalog,politics,politics_catalog,governance,governance_catalog,organization,organization_catalog,economy,relief_catalog,relief,tasks,task_governance,activity,[&](const StableId& id){const auto* action=common.action(id);if(!action)return common_failure("UnknownAction",id);const auto actor=action->actor_id;auto r=common.apply_resources({{ReleaseActionResources{id}},{}});if(!r.ok)return r;ActorMutation freed;freed.actor_id=actor;freed.action_id="";r=common.apply_actor(freed);if(!r.ok)return r;ActionMutation removed;removed.kind=ActionMutation::Kind::erase;removed.action.id=id;return common.apply_action(removed);}};}
    GovernanceEffects command(const StableId& actor,const GovernanceCommand& cmd){auto quote=need(preview_governance_business(read(),actor,cmd),"Real command preview");auto wire=encode_governance_quote(quote);quote=need(decode_governance_quote(wire),"Typed quote roundtrip");check(compare_boundary(wire,encode_governance_quote(quote)).exact(),"Quote roundtrip changed fields");Outcome<GovernanceEffects> applied;need(atomic([&](){auto context=write();applied=apply_governance_business(context,actor,cmd,quote);return Status{applied.ok,{},applied.error};}),"Real command apply");refresh();return need(std::move(applied),"Applied source IDs");}
};
void profile_boundaries(){using V=BoundaryValue;auto valid=boundary::obj({{"profile",V{"local_society_v1"}},{"politics",boundary::obj({{"enabled",V{true}}})},{"politics_governance",boundary::obj({{"enabled",V{true}}})},{"public_relief",boundary::obj({{"version",V{Integer{1}}}})}});check(read_politics_governance_profile(valid),"Joint profile rejected");check(!read_politics_governance_profile(boundary::obj({})),"Old absent profile activated");for(const auto* removed:{"politics_governance","public_relief","politics"}){auto bad=valid;auto& rows=*bad.as<V::Dict>();rows.erase(std::remove_if(rows.begin(),rows.end(),[&](const auto& x){return x.first==removed;}),rows.end());bool rejected=false;try{read_politics_governance_profile(bad);}catch(const boundary::DecodeFailure&){rejected=true;}check(rejected,"Partial profile accepted");}auto bad=valid;*bad.find("public_relief")->find("version")=V{Integer{2}};bool rejected=false;try{read_politics_governance_profile(bad);}catch(const boundary::DecodeFailure& e){rejected=e.error.original.code=="PublicReliefVersionMismatch";}check(rejected,"Unknown relief version accepted");}
// 真签发失败不得生成事实；受领读资源无写，实际开工预留，取消只释放本合同。
void actual_entry(){EntryWorld w;auto before=encode_common_state(w.common.state());GovernanceCommand issue=PoliticalGovernanceCommissionCommand{{"city","office",0,"official"},"worker","county","commission","granary",0};w.relief_catalog.policies.find("relief")->recipients.front().cash=59;auto bad=preview_governance_business(w.read(),"official",issue);check(!bad.ok&&bad.error.original.code=="ReliefFixedCostMismatch","Signing skipped actual relief plan");check(compare_boundary(before,encode_common_state(w.common.state())).exact(),"Signing preview mutated common");w.relief_catalog.policies.find("relief")->recipients.front().cash=60;auto issued=w.command("official",issue);check(w.governance.authorities.find(issued.authority_fact_id)&&issued.result_fact_id==issued.authority_fact_id,"Thin issue has no true political authority");GovernanceCommand accept=GovernanceAcceptCommand{issued.authority_fact_id,w.common.revision()};before=encode_common_state(w.common.state());auto quote=need(preview_governance_business(w.read(),"worker",accept),"Actual pure resource preview");check(w.tasks.tasks.empty()&&w.relief.commitments.empty()&&compare_boundary(before,encode_common_state(w.common.state())).exact(),"Acceptance preview invented Task or reservation");auto stale=quote;++stale.identity.execution_epoch;auto context=w.write();auto denied=apply_governance_business(context,"worker",accept,stale);check(!denied.ok&&denied.error.original.code=="StaleGovernanceQuote","Cross epoch quote accepted");auto started=w.command("worker",accept);check(w.common.action(started.action_id)&&w.common.action(started.action_id)->remaining_ticks==6&&w.tasks.tasks.find(started.task_id)&&need(w.common.spendable("public"),"Reserved spendable")==60,"Entry failed to open funded real action");auto cancelled=w.command("worker",GovernanceCancelCommand{started.task_id,w.common.revision()});check(!w.common.action(started.action_id)&&w.common.actor("worker")->action_id.empty()&&w.tasks.tasks.find(started.task_id)->status=="cancelled"&&w.relief.releases.find(cancelled.relief_fact_id)&&need(w.common.spendable("public"),"Released spendable")==180,"Cancellation did not preserve other reservation");w.validate();}
// 三百个真实但无关的当面签发，不得隐藏本人的一个待受领邀请或泄露另一名单。
void scoped_view(){EntryWorld w;for(int i=0;i<300;++i){auto issued=issue_governance_authority(w.common,*w.catalog,w.politics,w.governance,w.governance_catalog,w.organization,w.organization_catalog,w.activity,"official",{{"city","office",0,"official"},"official","county","commission","granary",0});if(!issued.ok)throw std::runtime_error("Unrelated actual issue: "+issued.error.original.code);}w.refresh();auto before=encode_common_state(w.common.state());auto page=need(query_governance_business(w.read(),"worker","site"),"Finite actual view");const auto& rows=boundary::array(boundary::field(page,"rows","page"),"rows");check(rows.size()==1&&boundary::get_string(rows.front(),"id","row")==w.authority_id,"Unrelated authority hid or leaked rows");check(!boundary::get_bool(page,"truncated","page")&&compare_boundary(before,encode_common_state(w.common.state())).exact(),"Finite view was contaminated or mutated");++w.common.state().identity.execution_epoch;auto stale=query_governance_business(w.read(),"worker","site");check(!stale.ok&&stale.error.original.code=="StaleGovernanceViewIndex","Old index survived restore epoch");w.refresh();need(query_governance_business(w.read(),"worker","site"),"Fresh final identity index");}
}
