int main(){try{profile_boundaries();actual_entry();scoped_view();std::cout<<"GOVERNANCE_ENTRY "<<checks<<" checks 0 failures; actual issue/accept/cancel, strict profile, scoped300 and identity; no full World claim\n";return 0;}catch(const std::exception& e){std::cerr<<"GOVERNANCE_ENTRY FAIL "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}

